mp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Prendre_le_contr&#244;le_dun_bateau_21&quot;&gt; Prendre le contr&#244;le d&#39;un bateau &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Faire_des_d&#233;g&#226;ts_&#224;_un_bateau_22&quot;&gt; Faire des d&#233;g&#226;ts &#224; un bateau &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#R&#233;parer_un_bateau_23&quot;&gt; R&#233;parer un bateau &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_engins_de_si&#232;ge_54&quot;&gt;Les engins de si&#232;ge&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_bases_55&quot;&gt; Les bases &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Manipulation_24&quot;&gt; Manipulation &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_25&quot;&gt; Dons &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Equipe_de_manipulation_26&quot;&gt; Equipe de manipulation &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Construire_un_engin_de_si&#232;ge_27&quot;&gt; Construire un engin de si&#232;ge &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Engins_de_si&#232;ge_de_ma&#238;tre_ou_magiques_28&quot;&gt; Engins de si&#232;ge de ma&#238;tre ou magiques &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#D&#233;sarmer_un_engin_de_si&#232;ge_29&quot;&gt; D&#233;sarmer un engin de si&#232;ge &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#R&#233;parer_un_engin_de_si&#232;ge_30&quot;&gt; R&#233;parer un engin de si&#232;ge &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;